package dev.gamersclt.batcaverna.nativeapp;
import android.app.Activity;import android.view.*;import android.widget.*;import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={23,35},manifest=Config.NONE)
public class GameFeedViewTest {
 @Test public void rendersGameCardAndUpdatesConfirmedLike()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();SessionPreferences.get(a).edit().putString("user_id","owner").apply();JSONObject event=new JSONObject().put("id","42").put("user_id","friend").put("created_at","2026-11-09T12:00:00Z").put("meta",new JSONObject().put("acao","started")).put("title",new JSONObject().put("nome","Prince of Persia").put("plataforma","PC")).put("author",new JSONObject().put("nome","Amigo"));int[] likes={0};GameFeedView feed=new GameFeedView(a,(action,data,cb)->{if(action.equals("list"))cb.done(new JSONArray().put(event),null);else {likes[0]++;try{cb.done(new JSONArray().put(new JSONObject().put("liked",true).put("like_count",1)),null);}catch(JSONException e){throw new AssertionError(e);}}});a.setContentView(feed);feed.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(840,View.MeasureSpec.EXACTLY));feed.layout(0,0,320,840);assertNotNull(find(feed,"Começou a jogar"));assertNotNull(find(feed,"Prince of Persia"));Button like=(Button)find(feed,"Curtir • 0");assertNotNull(like);like.performClick();assertEquals(1,likes[0]);assertEquals("Curtido • 1",like.getText().toString());assertTrue(like.isSelected());assertNull(find(feed,"Excluir publicação"));}
 @Test public void staleAccountResponseDoesNotRenderFriendsData()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();SessionPreferences.get(a).edit().putString("user_id","owner").apply();AccountRepository.Callback[] pending={null};GameFeedView feed=new GameFeedView(a,(action,data,cb)->pending[0]=cb);a.setContentView(feed);SessionPreferences.get(a).edit().putString("user_id","other").apply();pending[0].done(new JSONArray().put(new JSONObject().put("id","1").put("title",new JSONObject().put("nome","PRIVATE GAME"))),null);assertNull(find(feed,"PRIVATE GAME"));}
 private static View find(View root,String text){if(root instanceof TextView&&text.equals(((TextView)root).getText().toString()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View result=find(((ViewGroup)root).getChildAt(i),text);if(result!=null)return result;}return null;}
}
